window.ScripturaLexicons.BDAG_PART_0024 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-halon-bdag\" data-source=\"BDAG\" data-search=\"ἅλων halon eira debulha grão debulhado joeirar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅλων</td><td>Substantivo feminino</td><td>eira; grão debulhado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alopex-bdag\" data-source=\"BDAG\" data-search=\"ἀλώπηξ alopex raposa astúcia Herodes Antipas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλώπηξ</td><td>Substantivo feminino</td><td>raposa; pessoa astuta</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-halos-bdag\" data-source=\"BDAG\" data-search=\"ἅλως halos eira variante de ἅλων BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅλως</td><td>Substantivo feminino</td><td>ver ἅλων</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-halosis-bdag\" data-source=\"BDAG\" data-search=\"ἅλωσις halosis captura captura de animais apanha alimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅλωσις</td><td>Substantivo feminino</td><td>captura; apanha</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hama-bdag\" data-source=\"BDAG\" data-search=\"ἅμα hama ao mesmo tempo juntamente junto com simultaneamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅμα</td><td>Advérbio / preposição</td><td>ao mesmo tempo; juntamente; com</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amathes-bdag\" data-source=\"BDAG\" data-search=\"ἀμαθής amathes ignorante intérpretes incompetentes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμαθής</td><td>Adjetivo</td><td>ignorante</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amathios-bdag\" data-source=\"BDAG\" data-search=\"Ἀμάθιος Amathios Amátio pai Jonas Amitai BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμάθιος</td><td>Nome próprio masculino</td><td>Amátio</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amalek-bdag\" data-source=\"BDAG\" data-search=\"Ἀμαλήκ Amalek Amaleque tribo semítica deserto Sinai BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμαλήκ</td><td>Nome próprio masculino indeclinável</td><td>Amaleque</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hamaxa-bdag\" data-source=\"BDAG\" data-search=\"ἅμαξα hamaxa carro carroça vagão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅμαξα</td><td>Substantivo feminino</td><td>carro; carroça</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amarantinos-bdag\" data-source=\"BDAG\" data-search=\"ἀμαράντινος amarantinos imarcescível que não murcha coroa glória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμαράντινος</td><td>Adjetivo</td><td>imarcescível; que não murcha</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amarantos-bdag\" data-source=\"BDAG\" data-search=\"ἀμάραντος amarantos imarcescível imperecível flores herança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμάραντος</td><td>Adjetivo</td><td>imarcescível; imperecível</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hamartano-bdag\" data-source=\"BDAG\" data-search=\"ἁμαρτάνω hamartano pecar cometer erro transgredir errar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁμαρτάνω</td><td>Verbo</td><td>pecar; cometer erro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hamartema-bdag\" data-source=\"BDAG\" data-search=\"ἁμάρτημα hamartema pecado transgressão ato pecaminoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁμάρτημα</td><td>Substantivo neutro</td><td>pecado; transgressão</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hamartesis-bdag\" data-source=\"BDAG\" data-search=\"ἁμάρτησις hamartesis ato de pecar pecado atividade pecaminosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁμάρτησις</td><td>Substantivo feminino</td><td>ato de pecar; pecado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hamartia-bdag\" data-source=\"BDAG\" data-search=\"ἁμαρτία hamartia pecado pecaminosidade poder destrutivo mal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁμαρτία</td><td>Substantivo feminino</td><td>pecado; pecaminosidade; poder do pecado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amartyros-bdag\" data-source=\"BDAG\" data-search=\"ἀμάρτυρος amartyros sem testemunha testemunho revelado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμάρτυρος</td><td>Adjetivo</td><td>sem testemunha</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hamartolos-bdag\" data-source=\"BDAG\" data-search=\"ἁμαρτωλός hamartolos pecaminoso pecador outsider não observante gentio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁμαρτωλός</td><td>Adjetivo / substantivo</td><td>pecaminoso; pecador; pessoa de fora</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amasias-bdag\" data-source=\"BDAG\" data-search=\"Ἀμασίας Amasias Amazias rei Jerusalém genealogia Jesus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμασίας</td><td>Nome próprio masculino</td><td>Amazias</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amaurosis-bdag\" data-source=\"BDAG\" data-search=\"ἀμαύρωσις amaurosis escurecimento obscurecimento visão percepção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμαύρωσις</td><td>Substantivo feminino</td><td>escurecimento; obscurecimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-halon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅλων</h1><div class=\"entry-meta\"><span class=\"greek\">ωνος, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hálōn⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Forma variante, documentada desde Aristóteles, também em papiros [Mayser 287; Crönert p. ix]; LXX; GrBar 6:7; Jos., <em>Ant.</em> 20, 181, em lugar do ático — desde Ésquilo — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅλως\" data-meanings=\"eira; forma ática correspondente a ἅλων\">ἅλως</span>, genitivo <span class=\"greek\">ἅλω</span> ou <span class=\"greek\">ἅλωος</span>, encontrado em 1 Cl 29:3 [provavelmente segundo a LXX] e em inscrições [SIG 631, 7; 671A, 9], papiros [Mayser 258s.; PGM 4, 2746], LXX e Jos., <em>Ant.</em> 4, 281; veja W-S. §8, 13; B-D-F §44, 1; 52; Mlt-H. 121; 127.)</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Literalmente, <strong>superfície destinada à debulha do cereal, eira</strong>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γεννήματα ληνοῦ καὶ ἅλωνος\" data-meanings=\"produtos do lagar e da eira\">γεννήματα ληνοῦ καὶ ἅλωνος</span>, <strong>produtos do lagar e da eira</strong>, D 13:3 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 18.30</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θημωνιὰ ἅλωνος\" data-meanings=\"monte na eira\">θημωνιὰ ἅλωνος</span>, <strong>monte na eira</strong>, 1 Cl 56:15 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 5.26</a>).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Figuradamente, <strong>cereal debulhado que ainda permanece na eira, grão debulhado</strong> (PRyl 122, 10; 20 [séc. II d.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.39.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 39.12</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διακαθαίρειν τὴν ἅλωνα\" data-meanings=\"limpar; joeirar o que foi debulhado\">διακαθαίρειν τὴν ἅλωνα</span>, <strong>limpar (joeirar) o que foi debulhado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.17</a> (Just., <em>D.</em> 49, 3). — DELG. M-M.</p>\n</section></article><article id=\"entry-alopex-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλώπηξ</h1><div class=\"entry-meta\"><span class=\"greek\">εκος, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alṓpēx⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Desde Arquíloco [séc. VII a.C.], Heródoto; Platão, <em>Rep.</em> 365c; Teócrito 5, 112; grafito Sb 7223, 6 [séc. II a.C.]; LXX; En 89; Jos., <em>Ant.</em> 5, 295 [depois de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDG.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jz 15.4</a>]; SibOr 8, 41.) <span class=\"sense-number\">1.</span> Literalmente, <strong>raposa</strong>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱ ἀλώπεκες φωλεοὺς ἔχουσιν\" data-meanings=\"as raposas têm covis\">αἱ ἀ. φωλεοὺς ἔχουσιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.58</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Metaforicamente, com a <strong>astúcia da raposa</strong> em primeiro plano (Alceu [sécs. VII–VI a.C.] 42, 6 Diehl<sup>2</sup> [69, 6 L.-P.]; Teócrito 5, 112; sobre o rastro deixado por uma raposa, Plutarco, <em>Solon</em> 95e [30, 2] = Solon Fgm. 8, 5, Diehl<sup>3</sup> = West 11, 5; <em>Sulla</em> 469e [28, 5]; Epicteto 1, 3, 7; Artem. 2, 12 p. 104, 9; compare o símile de Píndaro, <em>P.</em> 2, 77, “como raposas quanto à disposição”; Billerb. II 678), sugerindo assim uma <strong>pessoa astuta</strong>, a respeito de Herodes Antipas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἴπατε τῇ ἀλώπεκι ταύτῃ\" data-meanings=\"dizei a essa raposa\">εἴπατε τῇ ἀλώπεκι ταύτῃ</span>, <strong>dizei a essa raposa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.32</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LAM.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lm 5.18</a>). — B. 186. DELG.</p>\n</section></article><article id=\"entry-halos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅλως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hálōs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅλων\" data-meanings=\"eira; grão debulhado\">ἅλων</span>.</p>\n</section></article><article id=\"entry-halosis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅλωσις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hálōsis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλίσκομαι\" data-meanings=\"ser tomado; ser capturado\">ἁλίσκομαι</span>, “ser tomado”; Píndaro, Heródoto e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 27.46</a>; Jos., <em>Ant.</em> 2, 250; 5, 261; SibOr 4, 89; Tat.; Mel., <em>P.</em> 26, 181; 56, 408.) <strong>Captura, apanha de animais para alimento</strong> (assim Aristóteles, <em>HA</em> 593a, 20; 600a, 3; Epicteto 4, 1, 29): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γεγεννημένα εἰς ἅλωσιν καὶ φθοράν\" data-meanings=\"nascidos para serem capturados e mortos\">γεγεννημένα εἰς ἅ. καὶ φθοράν</span>, <strong>nascidos para serem capturados e mortos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.12</a>. — DELG s.v. <span class=\"greek\">ἁλίσκομαι</span>.</p>\n</section></article><article id=\"entry-hama-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅμα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦háma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Homero+.) <span class=\"sense-number\">1.</span> Advérbio, marcador de <strong>ocorrência simultânea, ao mesmo tempo</strong>, denotando a coincidência temporal de duas ações (B-D-F §425, 2; índice de Rob.): <strong>ao mesmo tempo, juntamente</strong>, B 8:6; com particípio (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.41.7\" target=\"_blank\" rel=\"noopener noreferrer\">Is 41.7</a>; Jos., <em>Bell.</em> 3, 497; Just., <em>D.</em> 1, 1; 98, 1), <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅμα ἀνέντες τὰς ζευκτηρίας\" data-meanings=\"enquanto ao mesmo tempo soltavam as amarras\">ἅ. ἀνέντες τὰς ζευκτηρίας</span>, <strong>enquanto ao mesmo tempo soltavam as amarras</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.40</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">16.4</a> D. Com verbo finito, <strong>tudo de uma vez</strong>, Dg 8:11.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅμα (δὲ) καί\" data-meanings=\"ao mesmo tempo também; além disso\">ἅ. (δὲ) καί</span>, <strong>(mas) ao mesmo tempo também, além disso</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅμα καὶ ἐλπίζων\" data-meanings=\"ao mesmo tempo também esperando\">ἅ. καὶ ἐλπίζων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 24.26</a> (Jos., <em>Ant.</em> 18, 246 <span class=\"greek\">ἅ. καὶ ἀγόμενος</span>); <span class=\"greek\">ἅ. δὲ καὶ ἀργαὶ μανθάνουσιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5.13</a> (veja <span class=\"greek\">μανθάνω</span> 3); <span class=\"greek\">ἅ. δὲ καὶ ἑτοίμαζε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 22</a>. Em correlação, <span class=\"greek\">ἅμα … ἅμα καί</span>, <strong>em parte … em parte</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅμα διὰ τὴν ὑποψίαν τὴν πρὸς τὴν γυναῖκα, ἅμα καὶ διὰ τό μὴ φυγεῖν αὐτόν\" data-meanings=\"em parte pela suspeita em relação à mulher, em parte também para que ele não fugisse\">ἅμα διὰ τὴν ὑποψίαν τὴν πρὸς τὴν γυναῖκα, ἅμα καὶ διὰ τό μὴ φυγεῖν αὐτόν</span>, AcPl Ha 4, 8s. Em posição pós-positiva: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"προσευχόμενοι ἅμα καὶ περὶ ἡμῶν\" data-meanings=\"orando ao mesmo tempo também por nós\">προσευχόμενοι ἅμα καὶ περὶ ἡμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4.3</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Marcador de <strong>associação, juntamente</strong>. <strong>a.</strong> Como advérbio, denotando associação em alguma coisa (compare <span class=\"greek\">ἠφάνισαν νέον καὶ πρεσβύτην καὶ τέκνα αὐτῶν ἅμα</span>, PsSol 17:11), <strong>juntamente</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅμα ἠχρεώθησαν\" data-meanings=\"juntamente se tornaram inúteis\">ἅ. ἠχρεώθησαν</span> (como <bdi class=\"hebrew hebrew-term tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"יַחְדָּו\" data-transliteration=\"yaḥdāw\" data-meanings=\"juntamente; todos juntos\">יַחְדָּו</bdi>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.12</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 13.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.52.4\" target=\"_blank\" rel=\"noopener noreferrer\">52.4</a>).</p>\n<p class=\"entry-text\"><strong>b.</strong> Usado como preposição com dativo, <strong>juntamente com</strong> (Homero e outros; SIG 958, 21s.; 1168, 6; PRein 26, 14; POxy 975; 658, 13; 975; PFlor 21, 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 18.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.1.43\" target=\"_blank\" rel=\"noopener noreferrer\">1Esd 1.43</a> e outros; TestAbr A 10 p. 88, 5 [Stone p. 24]; TestJob 29:1; GrBar 17:1; Just., <em>A I</em>, 4, 9 e outros; Ath.): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκριζώσητε ἅμα αὐτοῖς\" data-meanings=\"arranqueis juntamente com eles\">ἐκριζώσητε ἅ. αὐτοῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.29</a>; <span class=\"greek\">ἅ. Ῥέῳ</span>, IPhld 11:1; compare IEph 2:1; 19:2; IMg 15 e outros.</p>\n<p class=\"entry-text\">Aparentemente pleonástico com <span class=\"greek\">σύν</span> (compare Alex. Aphr., <em>An.</em> 83, 19 <span class=\"greek\">ἅ. αἰσθομένη σὺν αὐτῷ</span>; En 9:7; Jos., <em>Ant.</em> 4, 309; compare SIG 705, 57 <span class=\"greek\">ἅμα μετ’ αὐτῶν</span>), para indicar o que pertence conjuntamente no tempo e no lugar, aproximadamente como o latim <em>una cum</em>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅμα σὺν αὐτοῖς ἁρπαγησόμεθα\" data-meanings=\"juntamente com eles seremos arrebatados\">ἅ. σὺν αὐτοῖς ἁρπαγησόμεθα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4.17</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅμα σὺν αὐτῷ ζήσωμεν\" data-meanings=\"juntamente com ele vivamos\">ἅ. σὺν αὐτῷ ζήσωμεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">5.10</a>. Também com advérbio de tempo (POxy 1025, 16 [séc. III d.C.] <span class=\"greek\">ἅμ’ αὔριον</span>; compare Jos., <em>Ant.</em> 6, 40 <span class=\"greek\">ἅ. ἕῳ</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅμα πρωΐ\" data-meanings=\"bem cedo pela manhã\">ἅ. πρωΐ</span>, <strong>bem cedo pela manhã</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.1</a> (Theophanes Continuatus 719, 7 [IBekker 1838]; compare EpArist 304 <span class=\"greek\">ἅ. τῇ πρωΐᾳ</span>). — DELG. M-M.</p>\n</section></article><article id=\"entry-amathes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμαθής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦amathḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Heródoto, Eurípides, Aristófanes e outros; PMert 82, 21 [séc. II d.C.]; Epicteto, <em>Ench.</em> 48, 3; Sl 48.11 Sym.; Fílon; Jos., <em>Ant.</em> 12, 191; Tat. 35, 2; Ath.; Iren. 3, 11, 9 [Harv. II 50, 12].) <strong>Ignorante</strong> (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀστήρικτος\" data-meanings=\"instável; sem firmeza\">ἀστήρικτος</span>), a respeito de intérpretes incompetentes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3.16</a> (compare Plutarco, <em>Mor.</em> 25c <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν πᾶσιν ἁμαρτωλὸν εἶναι τὸν ἀμαθῆ\" data-meanings=\"o ignorante erra em todas as coisas\">ἐν πᾶσιν ἁμαρτωλὸν εἶναι τὸν ἀμαθῆ</span>). — DELG s.v. <span class=\"greek\">μανθάνω</span>. M-M.</p>\n</section></article><article id=\"entry-amathios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀμάθιος</h1><div class=\"entry-meta\"><span class=\"greek\">ου</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Amáthios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(<bdi class=\"hebrew hebrew-term tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"אֲמִתַּי\" data-transliteration=\"ʾămittay\" data-meanings=\"Amitai; pai de Jonas\">אֲמִתַּי</bdi>, <span class=\"greek\">Αμαθι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JON.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jn 1.1</a>.) <strong>Amátio</strong>, pai de Jonas, AcPlCor 2:29.</p>\n</section></article><article id=\"entry-amalek-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀμαλήκ</h1><div class=\"entry-meta\"><span class=\"greek\">ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Amalḗk⟧</span><span class=\"separator\">·</span><span>indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(LXX, Fílon; TestSim 6:3; SibOr 8, 252; Just.; em Josefo, <span class=\"greek\">Ἀμάληκος, ου</span> [<em>Ant.</em> 2, 6].) <strong>Amaleque</strong>, uma tribo semítica no deserto do Sinai (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 17.8ss.</a>), B 12:9.</p>\n</section></article><article id=\"entry-hamaxa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅμαξα</h1><div class=\"entry-meta\"><span class=\"greek\">ης, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hámaxa⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁμα\" data-meanings=\"junto; simultaneamente\">ἁμα</span> + <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄξων\" data-meanings=\"eixo\">ἄξων</span>, “eixo”, com a ideia de ação simultânea sobre um eixo; Homero e outros; inscrições, papiros, LXX; TestSol 5:4; Josefo; Just., <em>D.</em> 132, 2.) <strong>Carro, carroça</strong>, Papias 3:2.</p>\n</section></article><article id=\"entry-amarantinos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμαράντινος</h1><div class=\"entry-meta\"><span class=\"greek\">η, ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦amarántinos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαραίνω\" data-meanings=\"murchar; definhar\">μαραίνω</span>, “murchar”.) <strong>Imarcescível, que não murcha</strong>; em nossa literatura, apenas figuradamente, da vida eterna: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν ἀμαράντινον τῆς δόξης στέφανον\" data-meanings=\"a coroa imarcescível da glória\">τὸν ἀ. τῆς δόξης στέφανον</span>, <strong>a coroa imarcescível da glória</strong> (<span class=\"greek\">στεφ. ἀ.</span> também Filóstrato, <em>Her.</em> 19, 14 p. 208, 18; talvez CIG 155, 39), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 5.4</a>.</p>\n<p class=\"entry-text\">Talvez se tenha em vista uma coroa de amarantos (Diosc. 4, 57 e Esopo, <em>Fab.</em> 384 H. = 369 P., <span class=\"greek\">τὸ ἀμάραντον</span>; ou Artem. 1, 77 p. 70, 19, <span class=\"greek\">ὁ ἀμάραντος</span>, a flor que <span class=\"greek\">μέχρι παντὸς διαφυλάττει</span>), ou de flores secas duradouras (“sempre-vivas”); sua qualidade de não murchar pode tipificar a glória eterna. Veja o verbete seguinte.</p>\n</section></article><article id=\"entry-amarantos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμάραντος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦amárantos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Diosc. 4, 57; Luciano, <em>Dom.</em> 9; escólio a Apolônio de Rodes 2, 399–401a; inscrição funerária do séc. II a.C., APF 1, 1901, 220; CIG II 2942c, 4 p. 1124; Sb 6:12.) Pertencente àquilo que <strong>não perde sua qualidade ou caráter original, imarcescível</strong>.</p>\n<p class=\"entry-text\"><strong>a.</strong> Literalmente, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμάραντα ἄνθη\" data-meanings=\"flores imarcescíveis\">ἀ. ἄνθη</span>, <strong>flores imarcescíveis</strong> — tal como florescem no mundo vindouro — ApcPt 5:15.</p>\n<p class=\"entry-text\"><strong>b.</strong> Figuradamente, da bem-aventurança eterna, com <span class=\"greek\">ἄφθαρτος</span> e <span class=\"greek\">ἀμίαντος</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμάραντος κληρονομία\" data-meanings=\"herança imarcescível; imperecível\">ἀ. κληρονομία</span>, <strong>herança imarcescível</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.4</a> (compare SibOr 8, 411, <span class=\"greek\">ζωὴ ἀ.</span>). — DELG s.v. <span class=\"greek\">μαραίνω</span>. M-M.</p>\n</section></article><article id=\"entry-hamartano-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁμαρτάνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hamartánō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἁμαρτήσω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.21</a>, compare Hm 4, 1, 1s. (W-S. §13, 8; Mlt-H. 227); segundo aoristo (Teógnis, Píndaro e outros) <span class=\"greek\">ἥμαρτον</span>, subjuntivo <span class=\"greek\">ἁμάρτω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.3</a>; primeiro aoristo no grego helenístico <span class=\"greek\">ἡμάρτησα</span>, subjuntivo <span class=\"greek\">ἁμαρτήσω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.15</a>; particípio <span class=\"greek\">ἁμαρτήσας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.14</a> (compare <span class=\"greek\">ἐπί</span> 6ac), 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.4</a>; perfeito <span class=\"greek\">ἡμάρτηκα</span>, LXX; 1ª pessoa do plural <span class=\"greek\">ἡμαρτήκαμεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1.10</a>; particípio perfeito passivo neutro <span class=\"greek\">ἡμαρτημένα</span> (Just.; Ath., <em>R.</em> 76, 10; veja B-D-F §75; 77; Mlt-H. 214; sobre as formas da LXX, veja Thackeray 259).</p>\n<p class=\"entry-text\"><strong>Cometer um erro, pecar</strong> — no sentido de “transgredir” contra divindade, costume ou lei desde Homero, especialmente na LXX, também nos pseudepígrafos, Fílon, Josefo, Herm. Wr., Just. e Ath.; no sentido geral de “errar o alvo, errar, fazer o que é errado”, Homero e outros; também Diógenes 37, 7 p. 158, 11 Malherbe; compare Papias 2:15 a respeito da compilação de Marcos.</p>\n<p class=\"entry-text\"><strong>a. Uso absoluto.</strong> (Menandro, Fgm. 499 K., <span class=\"greek\">ἄνθρωπος ὢν ἥμαρτον</span>; Herodas 5, 27; Diógenes 15 p. 108, 17 Malherbe; Orígenes, <em>C. Cels.</em> 1, 7, 7; Hipólito, <em>Ref.</em> 9, 15, 6.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.14</a>; 8.11; 9.2s. (compare Heródoto 1, 138); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.23</a>; 5.12 (veja a bibliografia em <span class=\"greek\">ἁμαρτία</span> 3b); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7.28</a>, 36; 15.34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.26</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 4.5</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1.10</a>; 2.1; 3.6, 9; 5.18; 1 Cl 4:4 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 4.7</a>); 56:13 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 5.24</a>); 2 Cl 1:2; B 10:10; Hv 3, 5, 5; m 4, 1, 4s.; 8; 4, 2, 2 e outros. Dos anjos que pecaram (En 106:14; compare 7:5; 20:6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.4</a>. Do diabo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.8</a>.</p>\n<p class=\"entry-text\"><strong>b.</strong> Com indicação mais completa daquilo em que consiste o erro ou fracasso moral, por meio de particípio suplementar (B-D-F §414, 5; compare Hipônax [séc. VI a.C.] 70 Diehl, <span class=\"greek\">οὐχ ἁμαρτάνω κόπτων</span>, “não erro quando golpeio”; Jos., <em>Ant.</em> 3, 174; compare Papias 2:15 acima): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἥμαρτον παραδοὺς αἷμα ἀθῷον\" data-meanings=\"pequei entregando sangue inocente\">ἥμαρτον παραδοὺς αἷμα ἀθῷον</span>, <strong>cometi pecado entregando sangue inocente</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.4</a>.</p>\n<p class=\"entry-text\"><strong>c.</strong> Com indicação da maneira de pecar (<span class=\"greek\">μέχρι ἐννοίας καὶ λόγου ἁ.</span>, Iren. 1, 6, 4 [Harv. I 56, 15]): <span class=\"greek\">ἀνόμως ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.12</a>, em oposição a <span class=\"greek\">ἐν νόμῳ ἁ.</span> no mesmo versículo; <span class=\"greek\">ἑκουσίως ἁ.</span> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.31.33\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 31.33</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.26</a>. Em oposição, <span class=\"greek\">εἴ τι ἄκοντες ἡμάρτετε</span>, 1 Cl 2:3 (veja <span class=\"greek\">ἄκων</span>). Também com acusativo (epigrama em Demóstenes 18, 289, <span class=\"greek\">μηδὲν ἁμαρτεῖν ἐστι θεῶν</span>): <span class=\"greek\">ἁ. ἁμαρτίαν</span> (= <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">חָטָא חֲטָאָה</bdi>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.32.30\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 32.30s.</a> e outros; compare Sófocles, <em>Phil.</em> 1249; Platão, <em>Phd.</em> 113e), <strong>cometer um pecado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5.16a</a>; <span class=\"greek\">ἁμαρτίας ἁ.</span>, Hv 2, 2, 4; também <span class=\"greek\">τοσαῦτα</span>, Hm 9:1 (Cornuto 10, <span class=\"greek\">τοιαῦτα ἁ.</span>). — <span class=\"greek\">ὑπὸ χεῖρα ἁ.</span>, <strong>pecar repetidamente</strong>, Hm 4, 3, 6 (B-D-F §232, 1).</p>\n<p class=\"entry-text\"><strong>d. Com indicação daquele contra quem o pecado é cometido.</strong> <strong>α.</strong> No dativo (M. Ant. 4, 26; 9, 4, <span class=\"greek\">ἑαυτῷ ἁμαρτάνει</span>; Sl 77.17; Bar 1:13; 2:5; ApcSed 15:8): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σοὶ μόνῳ ἥμαρτον\" data-meanings=\"contra ti somente pequei\">σοὶ μόνῳ ἥμαρτον</span>, <strong>contra ti somente pequei</strong>, 1 Cl 18:4 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.6\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.6</a>).</p>\n<p class=\"entry-text\"><strong>β.</strong> Outras construções: <span class=\"greek\">ἁ. εἴς τινα</span> (Heródoto 1, 138, <span class=\"greek\">εἰς τὸν ἥλιον</span>; Sófocles, Fgm. 21, <span class=\"greek\">εἰς θεούς</span>; igualmente Xenofonte, <em>Hell.</em> 1, 7, 19; Platão, <em>Phdr.</em> 242c, <span class=\"greek\">εἰς τὸ θεῖον</span>; Jd 5:20; 11:10; Sir 7:7; EpJer 12; ApcMos 32; Jos., <em>Ant.</em> 7, 320, <span class=\"greek\">εἰς τ. θεόν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.4</a>. <span class=\"greek\">εἰς Χριστόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 8.12</a>; <span class=\"greek\">εἰς τοὺς ἀδελφούς</span>, ibid.; <span class=\"greek\">εἰς τὸ ἴδιον σῶμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6.18</a> (compare Ésquines 1, 22). — <span class=\"greek\">εἰς τὸν οὐρανόν</span>, <strong>contra Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.18</a>, 21. <span class=\"greek\">ἁ. εἴς τινά τι</span> (M. Ant. 7, 26; BGU 1141, 14ss. [13 a.C.], <span class=\"greek\">ἡμάρτηκά τι εἰς σέ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.8</a>.</p>\n<p class=\"entry-text\"><strong>γ.</strong> <span class=\"greek\">ἁ. ἐνώπιόν τινος</span> (1Sm 7.6; 20.1; Tob 3.3; TestJob 15:6; JosAs 7:5; B-D-F §214, 6): <span class=\"greek\">ἐνώπιόν σου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.18</a>, 21.</p>\n<p class=\"entry-text\"><strong>e.</strong> Com indicação do resultado: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁμαρτάνειν μὴ πρὸς θάνατον\" data-meanings=\"cometer pecado que não leva à morte\">ἁ. μὴ πρὸς θάνατον</span>, <strong>cometer pecado que não leva à morte</strong> (como <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">חֵטְא לָמוּת</bdi>, Nm 18.22; <span class=\"greek\">λαβεῖν ἁμαρτίαν θανατηφόρον</span>; Dt 22.26, <span class=\"greek\">ἁμάρτημα θανάτου</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5.16b</a>. — R. Seeberg, L. Ihmels Festschr. 1928, 19–31; O. Bauernfeind, V. Schultze Festschr. 1931, 43–54; E. Burton, <em>ICC Gal.</em>, 436–443; O. Hey, “Ἁμαρτία”, <em>Philol.</em> 83, 1928, 1–17; 137–163; F. Steinleitner, <em>D. Beicht</em>, 1913; K. Latte, “Schuld u. Sünde in d. griech. Rel.”, <em>ARW</em> 20, 1921, 254–298. — DELG. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-hamartema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁμάρτημα</h1><div class=\"entry-meta\"><span class=\"greek\">τος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hamártēma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Com sentidos que vão de <strong>erro involuntário</strong> a <strong>grave falha moral</strong>: Aristóteles, <em>EN</em> 1135b; pré-socráticos, Sófocles e outros; Diodoro Sículo 14, 76, 4, <span class=\"greek\">εἰς θεοὺς ἁμαρτήματα</span>; POxy 34 III, 13; PTebt 5, 3 [veja <span class=\"greek\">ἀγνόημα</span>]; PParis 63 XIII, 2ss.; BGU 1141, 8; 1185, 7; LXX; En; PsSol 17:8; TestSol D; TestAbr A 14 p. 94, 22 [Stone p. 36]; ParJer 2:2; ApcEsdr, ApcMos; EpArist 297; Fílon; Jos., <em>Bell.</em> 4, 348; <em>Ant.</em> 1, 22; 3, 221 e outros; Mel., <em>P.</em> 103, 788 [B; <span class=\"greek\">ἁμαρτιῶν</span> Ch.]; Fgm. 12, 9; Teófilo de Antioquia 1, 2 [p. 60, 20].) Como ato individual, <strong>pecado, transgressão</strong> — como falha moral, Platão, <em>Phd.</em> 113e —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.16</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰώνιον ἁμάρτημα\" data-meanings=\"pecado eterno\">αἰώνιον ἁ.</span>, <strong>pecado eterno</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.29</a>; <span class=\"greek\">τὰ προγεγονότα ἁμαρτήματα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.25</a> (veja Eunápio p. 76 [B.], <span class=\"greek\">τὰ προγεγενημένα τῶν ἁμαρτημάτων</span>); compare <span class=\"greek\">τῶν πάλαι αὐτοῦ ἁμαρτημάτων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1.9</a> v.l.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐξαλείφειν τὰ πρότερα ἁ.</span>, <strong>apagar os pecados anteriores</strong>, 2 Cl 13:1; <span class=\"greek\">καθαρίζεσθαι ἀπὸ τῶν ἁ.</span>, <strong>ser purificado dos pecados</strong>, Hv 3, 2, 2; <span class=\"greek\">ποιεῖν ἁ.</span> (Heródoto 7, 194, 2; Jd 11.17; 13.16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6.18</a>. <span class=\"greek\">κρύπτειν τὸ ἁ.</span>, GJs 14:1; <span class=\"greek\">φανεροῦν τὸ ἁ.</span>, 16:1, 3. <span class=\"greek\">ἀφιέναι τινὶ τὰ ἁ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.13.39\" target=\"_blank\" rel=\"noopener noreferrer\">1Mc 13.39</a>), <strong>perdoar os pecados de alguém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.28</a>; PtK 3 p. 15, 27; GJs 5:1; para isso, <span class=\"greek\">ἰᾶσθαι τὰ ἁ.</span> (Platão, <em>Gorg.</em> 525b, <span class=\"greek\">ἰάσιμα ἁμαρτήματα ἁμαρτάνειν</span>), Hv 1, 1, 9; Hs 9, 23, 5; <span class=\"greek\">ποιεῖν ἴασιν τοῖς προτέροις ἁ.</span>, m 12, 6, 2; <span class=\"greek\">σῴζειν ἐκ τῶν ἁ.</span>, GJs 14:2.</p>\n<p class=\"entry-text\"><span class=\"greek\">τελειοῦν τὰ ἁ.</span>, GPt 5:17 = ASyn. 347, 60. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα κἀκεῖνοι τελειωθῶσιν τοῖς ἁμαρτήμασιν\" data-meanings=\"para que também eles sejam completados em seus pecados; para que se complete a medida de seus pecados\">ἵνα κἀκεῖνοι τελειωθῶσιν τοῖς ἁ.</span>, <strong>para que também eles sejam completados em seus pecados</strong>, isto é, para que se complete a medida dos pecados deles — os israelitas rebeldes do tempo de Moisés —, B 14:5. <span class=\"greek\">μετανοεῖν ἐπὶ τοῖς ἁ.</span>, <strong>arrepender-se dos pecados</strong>, 1 Cl 7:7 (Sb 12:19, <span class=\"greek\">ἐπὶ ἁμαρτήμασιν μετάνοια</span>; compare Apiano, <em>Bell. Civ.</em> 2, 63 §261s., <span class=\"greek\">ἐπὶ μετάνοιαν … τὸ ἁμάρτημα</span>). <span class=\"greek\">ἐφήδεσθαι τοῖς ἁ.</span>, <strong>deleitar-se nos pecados</strong>, Dg 9:1. — O. Hey, <em>Philol.</em> 83, 1928, 1–17, 137–163. — DELG s.v. <span class=\"greek\">ἁμαρτάνω</span>. M-M. TW.</p>\n</section></article><article id=\"entry-hamartesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁμάρτησις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hamártēsis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>A atividade de pecar, pecado</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐὰν … ἔτι ἁμάρτησις γένηται\" data-meanings=\"se ainda houver algum ato de pecar\">ἐὰν … ἔτι ἁ. γένηται</span>, <strong>se ainda houver algum ato de pecar</strong>, Hv 2, 2, 5.</p>\n</section></article><article id=\"entry-hamartia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁμαρτία</h1><div class=\"entry-meta\"><span class=\"greek\">ίας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hamartía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Com sentidos que vão de <strong>erro involuntário</strong> a <strong>ofensas graves contra uma divindade</strong>: Ésquilo, Antifonte, Demócrito e outros; inscrição de Cízico, <em>JHS</em> 27, 1907, p. 63 [séc. III a.C.], <span class=\"greek\">ἁμαρτίαν μετανόει</span>; PLips 119 recto, 3; POxy 1119, 11; LXX; En, TestSol, TestAbr, TestJob, Test12Patr; JosAs 12:14; ParJer, ApcEsdr, ApcSed, ApcMos; EpArist 192; Fílon; Jos., <em>Ant.</em> 13, 69 e outros; Ar. [Milne 76, 42]; Just., <em>A I</em> 61, 6; 10; 66, 1; <em>D.</em> 13, 1 e outros; Tat. 14, 1s.; 20, 1; Mel., <em>P.</em> 50, 359; 55, 400; veja <em>ClR</em> 24, 1910, 88; 234; 25, 1911, 195–197.)</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Desvio dos padrões humanos ou divinos de retidão, pecado</strong> — sendo normalmente o contexto que sugere o grau de gravidade —, tanto a própria ação (veja <span class=\"greek\">ἁμάρτησις</span>) como seu resultado (veja <span class=\"greek\">ἁμάρτημα</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶσα ἀδικία ἁμαρτία ἐστίν\" data-meanings=\"toda injustiça é pecado\">πᾶσα ἀδικία ἁ. ἐστίν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5.17</a> (compare Eurípides, <em>Or.</em> 649; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.50.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 50.17</a>). <span class=\"greek\">ἁ.</span> com <span class=\"greek\">ἀνομήματα</span>, Hv 1, 3, 1; descrita como <span class=\"greek\">ἀνομία</span> (compare Sl 58.3; TestJob 43:17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.4</a>; mas quem ama está longe do pecado, Pol 3:3; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4.8</a>; 1 Cl 49:5; Agr 13.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀναπληρῶσαι τὰς ἁ.</span>, <strong>completar a medida dos pecados</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 15.16</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2.16</a>; <span class=\"greek\">κοινωνεῖν ἁ. ἀλλοτρίαις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5.22</a>. <span class=\"greek\">ποιεῖν ἁ.</span>, <strong>cometer pecado</strong> (Tob 12.10; 14.7 S; Dt 9.21), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.4</a>, 8. Para isso também <span class=\"greek\">ἁμαρτάνειν ἁ.</span> (Êx 32.30; Lm 1.8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5.16</a>; <span class=\"greek\">ἐργάζεσθαι ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2.9</a>; Hm 4, 1, 2 — na LXX frequentemente <span class=\"greek\">ἐργάζεσθαι ἀδικίαν</span> ou <span class=\"greek\">ἀνομίαν</span>. <span class=\"greek\">μεγάλην ἁ. ἐργάζεσθαι</span>, <strong>cometer grande pecado</strong>, m 4, 1, 1; 8:2; plural Hs 7:2 (compare Platão, <em>Ep.</em> 7, 335a, <span class=\"greek\">τὰ μεγάλα ἁμαρτήματα κ. ἀδικήματα</span>).</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐπιφέρειν ἁ. τινί</span>, Hv 1, 2, 4; <span class=\"greek\">ἑαυτῷ ἁ. ἐπιφέρειν</span>, <strong>trazer pecado sobre si mesmo</strong>, m 11:4; para isso <span class=\"greek\">ἁ. ἐπισπᾶσθαί τινι</span>, m 4, 1, 8 (compare Is 5.18). <span class=\"greek\">προστιθέναι ταῖς ἁ.</span>, <strong>acrescentar aos próprios pecados</strong> (compare PsSol 3:10, <span class=\"greek\">προσέθηκεν ἁμαρτίας ἐφ’ ἁμαρτίας</span>), Hv 5:7; m 4, 3, 7; Hs 6, 2, 3; 8, 11, 3; <span class=\"greek\">φέρειν ἁ.</span>, 1 Cl 16:4 (Is 53.4); <span class=\"greek\">ἀναφέρειν</span>, v. 14 (Is 53.12); <span class=\"greek\">γέμειν ἁμαρτιῶν</span>, B 11:11; <span class=\"greek\">εἶναι ἐν ταῖς ἁμαρτίαις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.17</a> (compare Alex. Aphr., <em>Eth. Probl.</em> 9 II 2 p. 129, 13, <span class=\"greek\">ἐν ἁμαρτήμασιν εἶναι</span>).</p>\n<p class=\"entry-text\">O pecado visto da perspectiva da resposta de Deus ou de Cristo: <span class=\"greek\">ἀφιέναι τὰς ἁ.</span>, literalmente <strong>deixar ir</strong>, isto é, <strong>perdoar pecados</strong> (Lv 4.20 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.2</a>, 5s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.5</a>, 7, 9s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.20ss.</a>; Hv 2, 2, 4; 1 Cl 50:5; 53:5 (Êx 32.32) e outros (veja <span class=\"greek\">ἀφίημι</span> 2); daí <span class=\"greek\">ἄφεσις (τῶν) ἁμαρτιῶν</span> (Iren. 1, 21, 2 [Harv. I 182, 4]), <strong>perdão dos pecados</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.77\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.77</a>; 3.3; 24.47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.38</a>; 5.31; 10.43; 13.38; Hm 4, 3, 2; B 5:1; 6:11; 8:3; 11:1; 16:8. <span class=\"greek\">διδόναι ἄφεσιν ἁ.</span>, AcPl Ha 2, 30; <span class=\"greek\">λαβεῖν ἄφεσιν ἁ.</span>, <strong>receber perdão dos pecados</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 26.18</a> (Just., <em>D.</em> 54 e outros).</p>\n<p class=\"entry-text\"><span class=\"greek\">καθαρίζειν τὰς ἁ.</span>, <strong>purificar os pecados</strong>, concebidos como mancha, Hs 5, 6, 3; <span class=\"greek\">καθαρίζειν ἀπὸ ἁ.</span>, 1 Cl 18:3 (Sl 50.4; compare Sir 23.10; PsSol 10:1); também <span class=\"greek\">καθαρισμὸν ποιεῖσθαι τῶν ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.3</a>; <span class=\"greek\">ἀπολούεσθαι τὰς ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.16</a> ([com <span class=\"greek\">βαπτίζειν</span>] Just., <em>D.</em> 13, 1 e outros); <span class=\"greek\">λύτρον ἁ.</span>, <strong>resgate pelos pecados</strong>, B 19:10. — <span class=\"greek\">αἴρειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.29</a>; <span class=\"greek\">περιελεῖν ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.11</a>; <span class=\"greek\">ἀφαιρεῖν</span> (Êx 34.9; Is 27.9), v. 4; Hs 9, 28, 3; <span class=\"greek\">ῥυσθῆναι ἀπὸ ἁ.</span>, 1 Cl 60:3; <span class=\"greek\">ἀπὸ τῶν ἁ. ἀποσπασθῆναι</span>, AcPlCor 2:9.</p>\n<p class=\"entry-text\">O pecado como <strong>fardo</strong>: <span class=\"greek\">αἱ ἁ. κατεβάρησαν</span>, Hs 9, 28, 6; como <strong>doença</strong>: <span class=\"greek\">ἰᾶσθαι</span>, Hs 9, 28, 5 (compare Dt 30.3). Considerado como lançamento em um livro contábil: <span class=\"greek\">ἐξαλείφεται ἡ ἁ.</span>, <strong>é apagado, cancelado</strong> (Sl 108.14; Jr 18.23; Is 43.25), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.19</a>. Em oposição, <span class=\"greek\">στῆσαι τὴν ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.60\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.60</a>; <span class=\"greek\">λογίζεσθαι ἁ.</span>, <strong>levar o pecado em conta</strong>, como dívida — compare a metáfora comercial em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4.6</a> e F. Danker, Gingrich Festschr. 104 n. 2 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4.8</a> (Sl 31.2); 1 Cl 60:2 (Just., <em>D.</em> 141, 3). Passivo, <span class=\"greek\">ἁ. οὐκ ἐλλογεῖται</span>, <strong>não é lançado na conta</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.13</a> (G. Friedrich, <em>TLZ</em> 77, 1952, 523–528). De pecadores, <span class=\"greek\">ὀφειλέτης ἁ.</span>, Pol 6:1 (compare SIG 1042, 14–16 [séc. II d.C.], <span class=\"greek\">ὃς ἂν δὲ πολυπραγμονήσῃ τὰ τοῦ θεοῦ ἢ περιεργάσηται, ἁμαρτίαν ὀφειλέτω Μηνὶ Τυράννωι, ἣν οὐ μὴ δύνηται ἐξειλάσασθαι</span>).</p>\n<p class=\"entry-text\"><span class=\"greek\">γινώσκειν ἁ.</span> (compare Nm 32.23), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7.7</a>; <span class=\"greek\">ἐπίγνωσις ἁμαρτίας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.20</a>; <span class=\"greek\">ὁμολογεῖν τὰς ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1.9</a>; <span class=\"greek\">ἐξομολογεῖσθε ἐπὶ ταῖς ἁ.</span>, B 19:12; <span class=\"greek\">ἐξομολογεῖσθαι τὰς ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.5</a>; Hv 3, 1, 5s.; Hs 9, 23, 4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξομολογεῖσθε ἀλλήλοις τὰς ἁμαρτίας\" data-meanings=\"confessai uns aos outros os pecados\">ἐξομολογεῖσθε ἀλλήλοις τὰς ἁ.</span>, <strong>confessai uns aos outros os pecados</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.16</a>. — <span class=\"greek\">ἐλέγχειν τινὰ περὶ ἁ.</span>, <strong>convencer alguém de pecado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.46\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.46</a>; compare <span class=\"greek\">ἵνα σου τὰς ἁ. ἐλέγξω πρὸς τὸν κύριον</span>, <strong>para que eu revele teus pecados diante do Senhor</strong>, Hv 1, 1, 5.</p>\n<p class=\"entry-text\"><span class=\"greek\">σεσωρευμένος ἁμαρτίαις</span>, <strong>carregado de pecados</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3.6</a>; compare <span class=\"greek\">ἐπισωρεύειν ταῖς ἁ.</span>, B 4:6; <span class=\"greek\">ἔνοχος τῆς ἁ.</span>, <strong>envolvido no pecado</strong>, Hm 2:2; 4, 1, 5; <span class=\"greek\">μέτοχος τῆς ἁ.</span>, m 4, 1, 9. Em Hebreus, o pecado é expiado (<span class=\"greek\">ἱλάσκεσθαι τὰς ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.17</a>) por sacrifícios, <span class=\"greek\">θυσίαι ὑπὲρ ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5.1</a> (compare 1 Cl 41:2); <span class=\"greek\">προσφορὰ περὶ ἁ.</span>, <strong>oferta pelo pecado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.18</a>; também simplesmente <span class=\"greek\">περὶ ἁ.</span> (Lv 5.11; 7.37), vv. 6, 8, ambos citando Sl 39.7; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3.18</a>. <span class=\"greek\">προσφέρειν περὶ ἁ.</span>, <strong>oferecer uma oferta pelo pecado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5.3</a>; compare 10.12; 13.11. Cristo fez o sacrifício perfeito pelo pecado, 9.23ss.; <span class=\"greek\">συνείδησις ἁ.</span>, <strong>consciência de pecado</strong>, 10.2; <span class=\"greek\">ἀνάμνησις ἁ.</span>, <strong>recordação de pecados</strong>, da festa da expiação, v. 3.</p>\n<p class=\"entry-text\"><strong>b. Pecados especiais.</strong> (<span class=\"greek\">ἁ. τῆς ἀποστασίας</span>, Iren. 5, 26, 2 [Harv. II 397, 4].) <span class=\"greek\">πρὸς θάνατον</span>, <strong>que leva à morte</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5.16b</a> (veja <span class=\"greek\">ἁμαρτάνω</span> e); em oposição, <span class=\"greek\">οὐ πρὸς θάνατον</span>, v. 17. <span class=\"greek\">μεγάλη ἁ.</span>, <strong>grande pecado</strong>, Hv 1, 1, 8 e outros (Gn 20.9; Êx 32.30 e outros; compare escólio a Platão, <em>Tht.</em> 189d, <span class=\"greek\">ἁμαρτήματα μεγάλα</span>); <span class=\"greek\">μείζων ἁ.</span>, m 11:4; <span class=\"greek\">ἥττων</span>, 1 Cl 47:4; <span class=\"greek\">μεγάλη κ. ἀνίατος</span>, Hm 5, 2, 4; <span class=\"greek\">τέλειαι ἁ.</span>, Hv 1, 2, 1; B 8:1; compare <span class=\"greek\">τὸ τέλειον τῶν ἁ.</span>, 5:11 (Fílon, <em>Mos.</em> 1, 96, <span class=\"greek\">κατὰ τῶν τέλεια ἡμαρτηκότων</span>); <span class=\"greek\">ἡ προτέρα ἁ.</span> (Arriano, <em>Anab.</em> 7, 23, 8, <span class=\"greek\">εἴ τι πρότερον ἡμάρτηκας</span>), <strong>pecado cometido antes do batismo</strong>, Hm 4, 1, 11; 4, 3, 3; Hs 8, 11, 3; compare v 2, 1, 2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Estado de ser pecaminoso, pecaminosidade</strong>, traço proeminente do pensamento joanino e em oposição a <span class=\"greek\">ἀλήθεια</span>; daí <span class=\"greek\">ἁ. ἔχειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9.41</a>; 15.24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1.8</a>; <span class=\"greek\">μείζονα ἁ. ἔχειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.11</a>; <span class=\"greek\">ἁ. μένει</span>, 9.41; <span class=\"greek\">γεννᾶσθαι ἐν ἁμαρτίαις</span>, <strong>nascer em pecado</strong>, 9.34 (<span class=\"greek\">ἐν ἁμαρτίᾳ</span> v.l.); em oposição, <span class=\"greek\">ἐν ἁ. ἀποθανεῖν</span>, <strong>morrer em pecado</strong>, 8.21, 24; AcPl Ha 1, 16; <span class=\"greek\">ἁ. ἐν αὐτῷ οὐκ ἔστιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.5</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Poder maligno destrutivo, pecado.</strong> <strong>a.</strong> Paulo pensa no pecado quase em termos pessoais (compare Sir 27.10; Mel., <em>P.</em> 50, 359; PGM 4, 1448, com outras divindades do mundo inferior, também <span class=\"greek\">Ἁμαρτίαι χθόνιαι</span>; Dibelius, <em>Geisterwelt</em> 119ss.), como poder dominante que invade o mundo. O pecado entrou no mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.12</a> (J. Freundorfer, <em>Erbsünde u. Erbtod b. Ap. Pls</em>, 1927; E. Lohmeyer, <em>ZNW</em> 29, 1930, 1–59; J. Schnitzer, <em>D. Erbsünde im Lichte d. Religionsgesch.</em>, 1931; R. Otto, <em>Sünde u. Urschuld</em>, 1932; F. Danker, “Ro 5:12: Sin under Law”, <em>NTS</em> 14, 1967/68, 424–439), reina ali, v. 21; 6.14; tudo foi submetido a ele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3.22</a>; as pessoas o servem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.6</a>; são seus escravos, vv. 17, 20; são vendidas ao seu serviço, 7.14, ou libertadas dele, 6.22; ele tem sua lei, 7.23; 8.2; revive (<span class=\"greek\">ἀνέζησεν</span>), 7.9, ou está morto, v. 8; paga seu salário, isto é, a morte, 6.23; compare 5.12 — veja a bibliografia s.v. <span class=\"greek\">ἐπί</span> 6c. Como princípio quase pessoal, habita nos seres humanos, 7.17, 20, isto é, na carne (veja <span class=\"greek\">σάρξ</span> 2cα), 8.3; compare v. 2; 7.25. O corpo terreno é, portanto, <span class=\"greek\">σῶμα τῆς ἁ.</span>, 6.6 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2.11</a> v.l.).</p>\n<p class=\"entry-text\">Como abstrato em lugar do concreto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν μὴ γνόντα ἁμαρτίαν ὑπὲρ ἡμῶν ἁμαρτίαν ἐποίησεν\" data-meanings=\"aquele que não conheceu pecado, Deus o fez pecado por nós\">τὸν μὴ γνόντα ἁ. ὑπὲρ ἡμῶν ἁμαρτίαν ἐποίησεν</span>, <strong>Deus fez aquele que nunca pecou ser pecado — isto é, o culpado — por nossa causa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5.21</a>.</p>\n<p class=\"entry-text\"><strong>b.</strong> Em Hebreus — como no Antigo Testamento — o pecado aparece como o poder que engana a humanidade e a conduz à destruição, e cuja influência e atividade só podem ser encerradas por sacrifícios (veja 1a, fim): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπάτη τῆς ἁμαρτίας\" data-meanings=\"engano do pecado\">ἀπάτη τῆς ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.13</a>.</p>\n<p class=\"entry-text\">Sobre o verbete inteiro, veja <span class=\"greek\">ἁμαρτάνω</span>, fim; G. Moore, <em>Judaism</em> I 445–452; A. Büchler, <em>Studies in Sin and Atonement in the Rabb. Lit. of the I Cent.</em>, 1928; W. Knuth, <em>D. Begriff der Sünde b. Philon v. Alex.</em>, diss. Jena, 1934; E. Thomas, <em>The Problem of Sin in the NT</em>, 1927; Dodd 76–81; D. Daube, <em>Sin, Ignorance and Forgiveness in the Bible</em>, 1961; A. Gelin e A. Descamps, <em>Sin in the Bible</em>, 1965. Sobre a questão especial “The Christian and Sin”, veja P. Wernle 1897; H. Windisch 1908; E. Hedström 1911; R. Bultmann, <em>ZNW</em> 23, 1924, 123–140; Windisch, ibid. 265–281; R. Schulz, <em>D. Frage nach der Selbsttätigkt. d. Menschen im sittl. Leben b. Pls.</em>, diss. Heidelberg, 1940; J. Addison, <em>ATR</em> 33, 1951, 137–148; K. Kuhn, “πειρασμός ἁμαρτία σάρξ im NT”, <em>ZTK</em> 49, 1952, 200–222; J. Bremer, <em>Hamartia</em>, 1969 — perspectivas gregas. — B. 1182. EDNT. DELG s.v. <span class=\"greek\">ἁμαρτάνω</span>. M-M. TW.</p>\n</section></article><article id=\"entry-amartyros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμάρτυρος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦amárturos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Desde Tucídides 2, 41, 4; também Calímaco, Fgm. 612 [442 Schn.], <span class=\"greek\">ἀμάρτυρον οὐδὲν ἀείδω</span>, “não anuncio nada que não seja atestado”; Herodiano 1, 1, 3; Ins. Ariassi 58, 8 [<em>BCH</em> 16, 1892, p. 428]; CPR 232, 30; PFlor 59, 13 [séc. III d.C.], <span class=\"greek\">ἵνα μὴ ἀμάρτυρον ᾖ</span>; POxy 2187, 10; Fílon, <em>Sacr. Abel.</em> 34; Jos., <em>Ant.</em> 14, 111; Ath. 24, 5, <span class=\"greek\">ἴστε μηδὲν ἡμᾶς ἀμάρτυρον λέγειν</span>; Iren. 1, 8, 1 [Harv. I 67, 2].) <strong>Sem testemunha, não atestado.</strong> De Deus: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἁμάρτυρον αὑτὸν ἀφῆκεν\" data-meanings=\"não deixou a si mesmo sem testemunho\">οὐκ ἁμάρτυρον αὑτὸν ἀφῆκεν</span>, <strong>Deus não deixou a si mesmo sem testemunho</strong>, isto é, revelou-se claramente — como benfeitor; veja F. Danker, <em>Benefactor</em>, 1982, 442–447 e s.v. <span class=\"greek\">μαρτυρέω</span>, <span class=\"greek\">μαρτυρία</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 14.17</a>. Em Filóstrato, <em>Vi. Apoll.</em> 6, 1 p. 204, 3, <span class=\"greek\">ἀμ.</span> significa simplesmente “desconhecido”, de território inexplorado. — DELG s.v. <span class=\"greek\">μάρτυς</span>. M-M.</p>\n</section></article><article id=\"entry-hamartolos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁμαρτωλός</h1><div class=\"entry-meta\"><span class=\"greek\">όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hamartōlós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Pertencente a comportamento ou atividade que não corresponde aos padrões esperados de ordem moral ou cultual. Ser considerado <strong>pessoa de fora</strong> por não se conformar a determinadas normas é componente semântico frequente. Pessoas de certas ocupações — por exemplo, pastoreio e curtimento de couro — que punham em risco a pureza cultual podiam ser consideradas por alguns “pecadores”, termo equivalente a “pessoa de fora”. Não israelitas eram especialmente considerados fora dos limites — compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.28</a> e veja b abaixo.</p>\n<p class=\"entry-text\"><strong>a. Como adjetivo</strong> (Aristófanes, <em>Th.</em> 1111; Aristóteles, <em>EN</em> 2, 9, 1109a 33; Filodemo, <em>Ira</em> p. 73 W.; Plutarco, <em>Mor.</em> 25c; LXX; TestAbr A 9 p. 86, 22 [Stone p. 20]; Just., <em>A I</em> 15, 5; <em>D.</em> 43, 3 e outros), <strong>pecaminoso</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τῇ γενεᾷ ταύτῃ τῇ μοιχαλίδι καὶ ἁμαρτωλῷ\" data-meanings=\"nesta geração adúltera e pecaminosa\">ἐν τῇ γενεᾷ ταύτῃ τῇ μοιχαλίδι καὶ ἁ.</span>, <strong>nesta geração adúltera (= infiel) e pecaminosa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.38</a>. <span class=\"greek\">ἵνα γένηται καθ’ ὑπερβολὴν ἁ. ἡ ἁμαρτία</span>, <strong>para que o pecado se tornasse pecaminoso em extremo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7.13</a>.</p>\n<p class=\"entry-text\">Com foco na não conformidade cultual, <span class=\"greek\">ἀνὴρ ἁ.</span> (Sir 15.12; 27.30; 1Mc 2.62), <strong>homem pecador</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.8</a>; 19.7; <span class=\"greek\">ἄνθρωπος ἁ.</span> (Sir 11.32; 32.17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9.16</a>; plural (Nm 32.14; Just., <em>D.</em> 23, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.7</a>.</p>\n<p class=\"entry-text\"><strong>b. Como substantivo.</strong> <strong>α.</strong> <span class=\"greek\">ὁ ἁ.</span>, <strong>o pecador</strong>, geralmente com foco no procedimento errado em si. Inscrições da Lícia: <span class=\"greek\">ἁ. θεοῖς</span>, “pecador contra os deuses” [IAsMinLyk I, 30, nº 7; CIG 4307; inscrição lícia, <em>ARW</em> 19, 1919, 284], ou <span class=\"greek\">ἁ. θεῶν</span> [IAsMinLyk II, 36, nº 58; OGI 55, 31s.; CIG 4259, 6]; outras inscrições, Steinleitner [veja <span class=\"greek\">ἁμαρτάνω</span>, fim] p. 84s.; LXX, En, TestAbr, ApcEsdr, ApcSed, ApcMos, Test12Patr; Just., <em>A I</em> 15, 8 e outros. <span class=\"greek\">ἁ. παρὰ πάντας τοὺς Γαλιλαίους</span>, <strong>pecadores maiores que todos os outros galileus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.2</a>; em oposição a <span class=\"greek\">δίκαιος</span>, como En 104:6: <span class=\"greek\">οὐκ ἦλθον καλέσαι δικαίους, ἀλλὰ ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.32</a>; 2 Cl 2:4; B 5:9; compare Hs 3:2s.; 4:2ss.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">ἀσεβής</span> (En 5:6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4.18</a> (Pr 11.31); B 11:7 (Sl 1.5); com <span class=\"greek\">πονηρός</span> (Gn 13.13), 4:2; com <span class=\"greek\">ἄπιστος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21.8</a> v.l.; <span class=\"greek\">ἁ. εἰμι</span>, Hm 4, 2, 3; <span class=\"greek\">οὗτος ὁ ἄνθρωπος ἁ. ἐστιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9.24</a>, compare v. 25; <span class=\"greek\">ἁ. μετανοῶν</span>, <strong>pecador que se arrepende</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.7</a>, 10; <span class=\"greek\">μετάνοια τῶν ἁ.</span>, Hs 8, 6, 6; <span class=\"greek\">ἁμαρτωλοὺς προσδέχεσθαι</span>, Lc 15.2; <span class=\"greek\">ἁ. σῶσαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1.15</a>; <span class=\"greek\">ἐπιστρέφειν ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.20</a>; <span class=\"greek\">ἱλάσθητί μοι τῷ ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18.13</a>; <span class=\"greek\">ἁμαρτωλῶν οὐκ ἀκούει</span>, de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9.31</a>; <span class=\"greek\">ἡ ἁμαρτωλός</span>, <strong>a mulher pecadora</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.37</a>, 39 (P. Joüon, <em>RSR</em> 29, 1939, 615–619). Em interpelação retórica, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4.8</a>.</p>\n<p class=\"entry-text\"><strong>β. Com foco no status de pessoa de fora.</strong> Com <span class=\"greek\">τελώνης</span> (I. Abrahams, “Publicans and Sinners”, <em>Studies in Pharisaism and the Gospels</em> I, 1917, 54ss.; J. Jeremias, <em>ZNW</em> 30, 1931, 293–300; W. Raney, <em>JR</em> 10, 1930, 578–591; Goodsp., <em>Probs.</em> 28s.), <strong>pessoas irreligiosas, não observantes, pessoas de fora</strong>, isto é, os que não observavam a Lei em detalhe e por isso eram evitados pelos observadores dos preceitos tradicionais: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.10s.</a>; 11.19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.15s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.30</a>; 7.34; 15.1. Lc 6.32 tem <span class=\"greek\">ἁ.</span>, enquanto seu paralelo Mt 5.46 tem <span class=\"greek\">τελώνης</span>.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">ἔθνη</span>, Hs 4:4; mais precisamente <span class=\"greek\">ἡμεῖς οὐκ ἐξ ἐθνῶν ἁμαρτωλοί</span>, que significa, no uso de judeus e cristãos judeus, <strong>não “pecadores” de origem gentílica</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2.15</a>. Em geral, termo favorito para não israelitas (Is 14.5; Tob 13.8; 1Mc 1.34 e outros); daí a ironia em <span class=\"greek\">ὁ υἱὸς τ. ἀνθρώπου παραδίδοται εἰς (τὰς) χεῖρας (τῶν) ἁ.</span> — o israelita Jesus entregue às mãos dos “de fora”, gentios —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.41</a> (sobre <span class=\"greek\">χεῖρ. ἁ.</span>, compare Sl 70.4; 81.4; 96.10); compare Lc 6.32ss., cujo paralelo Mt 5.47 tem <span class=\"greek\">ἐθνικός</span>. <span class=\"greek\">(ἡ) ὁδὸς ἁμαρτωλῶν</span>, <strong>caminho de pecadores</strong>, B 10:10 (Sl 1.1). Seu caráter adjetival desaparece inteiramente em Jd 15, onde o próprio termo é modificado por <span class=\"greek\">ἀσεβεῖς</span> (En 1:9).</p>\n<p class=\"entry-text\">Do estado de uma pessoa ainda não reconciliada: <span class=\"greek\">ἔτι ἁ. ὄντων ἡμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.8</a>. <span class=\"greek\">ἁ. κατεστάθησαν οἱ πολλοί</span>, <strong>os muitos — isto é, a humanidade, em oposição ao “um”, Adão — foram constituídos pecadores</strong>, isto é, ficaram expostos a ser tratados como pecadores; veja <span class=\"greek\">καθίστημι/καθιστάνω</span> 3, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.19</a>. <span class=\"greek\">ὡς ἁμαρτωλὸς κρίνομαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.7</a>; <span class=\"greek\">εὑρέθημεν ἁμαρτωλοί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2.17</a>. Em oposição, <span class=\"greek\">κεχωρισμένος ἀπὸ τῶν ἁ.</span>, <strong>separado dos pecadores</strong>, de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7.26</a>; <span class=\"greek\">ὑπό τῶν ἁ. … ἀντιλογίαν</span>, 12.3. — E. Sjöberg, <em>Gott u. die Sünder im paläst. Judentum</em>, 1938. — DELG s.v. <span class=\"greek\">ἁμαρτάνω</span>. M-M. TW.</p>\n</section></article><article id=\"entry-amasias-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀμασίας</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Amasías⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(<bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">אֲמַצְיָה</bdi>.) <strong>Amazias</strong>, rei em Jerusalém (2Cr 25.1; 4Rs 14.1; Jos., <em>Ant.</em> 9, 186), na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.23ss.</a> D; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1.8</a> <span class=\"abbr tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"abbr\" data-tooltip-label=\"syc.\" data-tooltip-text=\"sincronismo\">syc.</span></p>\n</section></article><article id=\"entry-amaurosis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμαύρωσις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦amaúrōsis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>Escurecimento, obscurecimento</strong> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμαυρός\" data-meanings=\"dificilmente visto; quase invisível\">ἀμαυρός</span>, “dificilmente visto, quase invisível”, como <em>Od.</em> 4, 824 e 835, de uma aparição; Hipócrates e outros; Plutarco, <em>Anton.</em> 949 [71, 8]; Vett. Val. 109, 31; 110, 36; Herm. Wr. 3, 4). Em nossa literatura, apenas figuradamente, da percepção (Aristóteles, <em>De Anima</em> 408b, 20, de embotamento mental; com <span class=\"greek\">ἀχλύς</span>, como Jos., <em>Ant.</em> 9, 57), de politeístas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμαύρωσιν περικείμενοι\" data-meanings=\"afligidos por obscurecimento da visão\">ἀμαύρωσιν περικείμενοι</span>, <strong>afligidos por obscurecimento da visão</strong>, 2 Cl 1:6. — DELG s.v. <span class=\"greek\">ἀμαυρός</span>.</p>\n</section></article>"};
